	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.kYCDocumentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for KYCDocument : " + successValue.getKYCDocumentId());
							  if (successValue.getKYCDocumentId().equals(kYCDocumentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfKYCDocumentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("KYCDocument test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on kYCDocument consumed")
					);
			subscriber.kYCDocumentSubscribe( kYCDocumentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for KYCDocument : " + successValue.getKYCDocumentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfKYCDocumentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on kYCDocument for kYCDocumentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a KYCDocument. 
	 */
	protected KYCDocument read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created KYCDocument" );

		KYCDocument entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read KYCDocument with primary key" );
		msg.append( kYCDocumentId );
		
		KYCDocumentFetchOneSummary fetchOneSummary = new KYCDocumentFetchOneSummary( kYCDocumentId );

		try {
			entity = KYCDocumentService.getKYCDocumentInstance().getKYCDocument( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found KYCDocument " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a KYCDocument.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a KYCDocument." );

		StringBuilder msg = new StringBuilder( "Failed to update a KYCDocument : " );        
		KYCDocument entity = read();
		UpdateKYCDocumentCommand command = generateUpdateCommand();
		command.setKYCDocumentId(entity.getKYCDocumentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created KYCDocument." );

			// for use later on...
			kYCDocumentId = entity.getKYCDocumentId();

			KYCDocumentService proxy = KYCDocumentService.getKYCDocumentInstance();  

			proxy.updateKYCDocument( command ).get();

			LOGGER.info( "-- Successfully saved KYCDocument - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + kYCDocumentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a KYCDocument.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created KYCDocument." );

		KYCDocument entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read KYCDocument with id " + kYCDocumentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read KYCDocument with id " + kYCDocumentId );

			throw e;
		}

		try{
			KYCDocumentService.getKYCDocumentInstance().delete( new DeleteKYCDocumentCommand( entity.getKYCDocumentId() ) ).get();
			LOGGER.info( "-- Successfully deleted KYCDocument with id " + kYCDocumentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete KYCDocument with id " + kYCDocumentId );

			throw e;
		}
	}

	/**
	 * get all KYCDocuments.
	 */
	protected List<KYCDocument> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of KYCDocuments:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all KYCDocument : " );        
		List<KYCDocument> collection  = new ArrayList<>();

		try {
			// call the static get method on the KYCDocumentService
			collection = KYCDocumentService.getKYCDocumentInstance().getAllKYCDocument();
			assertNotNull( collection, "An Empty collection of KYCDocument was incorrectly returned.");
			
			// Now print out the values
			KYCDocument entity = null;            
			Iterator<KYCDocument> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getKYCDocumentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

